; Pose of both fighters from the move step (not in V 05 05 87)
; $8620-$863c

; Not in build V 05 05 87. Sets fighter_pose of both fighters from the move sequence: the byte before fighter_move_step, or byte 0 at step 0.
set_fighter_poses
        ldx #$01
set_fighter_poses_loop
        lda fighter_move,x
        asl
        tay
        lda move_seq_ptrs,y
        sta move_seq_ptr
        lda move_seq_ptrs+1,y
        sta move_seq_ptr+1
        ldy fighter_move_step,x
        beq set_fighter_poses_read
        dey
set_fighter_poses_read
        lda (move_seq_ptr),y            ; Pose byte of the move sequence.
        sta fighter_pose,x
        dex
        bpl set_fighter_poses_loop
        rts
